type CustomImageType = FieldDefinition & {
  fields?: Array<{
    name: string;
    title: string;
    type: "string" | "boolean";
  }>;
};

const accessibleImage: CustomImageType = {
  name: "accessibleImage ",
  type: "image",
  title: "Accessible Image ",
